INSERT INTO `battle_pet_species_locale` (`ID`, `locale`, `Description_lang`, `SourceText_lang`, `VerifiedBuild`) VALUES
(5164, 'deDE', 'Er hat sich beim Wühlen nach magischen Abfällen in Silbermond ordentlich in die Nesseln gesetzt. Zum Glück konntet Ihr ihn da rausholen!', '|cFFFFD200Zone: |rSilbermond|n', 69497),
(5077, 'deDE', '', '', 69497);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(318840, 'deDE', '', 'Die Geister nehmen un\' die Geister geb\'n. Versucht Euer Glück beim nächsten Mal.', 69497),
(317406, 'deDE', '(Schmerzensschreie)', '', 69497),
(317402, 'deDE', '(schnappt nach Luft)', '', 69497),
(317398, 'deDE', '(atmet schwer)', '', 69497),
(318450, 'deDE', '', 'Das ist unser Ziel.', 69497),
(318448, 'deDE', '', 'Schnell, verbergt Euch in den Schatten!', 69497),
(314045, 'deDE', '', 'Erschreckt mich doch nicht so.', 69497),
(314044, 'deDE', '', 'Wieder im Ring.', 69497),
(314043, 'deDE', '', 'Ihr kämpft mit mir, und das bleibt auch so.', 69497),
(314042, 'deDE', '', 'Sterbt mir bloß nicht weg!', 69497),
(314010, 'deDE', '', 'Rückzug! Wir müssen uns neu sammeln.', 69497),
(313727, 'deDE', '', 'Ich gebe Euch Deckung.', 69497),
(313723, 'deDE', '', 'Tötet sie. Stärkt mich!', 69497),
(313717, 'deDE', '', 'Es gibt nur eine Valeera. Nieder mit ihr!', 69497),
(321873, 'deDE', '', 'Ihre Hand halten.', 69497),
(320494, 'deDE', '', 'Danke, $n. Auch wenn Ihr sie nich\' rett\'n konntet, diese Informationen werd\'n andere Leben rett\'n.', 69497),
(319326, 'deDE', '1... 2... 3...\n\nOh! Äh, hallo!\n\nWir haben nur Verstecken gespielt. Die anderen verstecken sich gerade. Mich lassen sie nie. Sie sagen, ich wäre zu leicht zu finden...\n\nAber Ihr seht wie ein guter Sucher aus! Viel besser als ich...\n\nWollt Ihr versuchen, sie zu finden?\n\nAber Ihr solltet wissen, dass sie immer echt gute Verstecke finden.\n\n5... 6... 7...', '1... 2... 3...\n\nOh! Äh, hallo!\n\nWir haben nur Verstecken gespielt. Die anderen verstecken sich gerade. Mich lassen sie nie. Sie sagen, ich wäre zu leicht zu finden...\n\nAber Ihr seht wie ein guter Sucher aus! Viel besser als ich...\n\nWollt Ihr versuchen, sie zu finden?\n\nAber Ihr solltet wissen, dass sie immer echt gute Verstecke finden.\n\n5... 6... 7...', 69497),
(318831, 'deDE', 'Diebin...', '', 69497),
(318533, 'deDE', '', 'Was wir alles durchgemacht ham...\n\nEs darf nich\' umsonst sein.', 69497),
(318238, 'deDE', 'Was? Er hat das ganze Dorf getötet? Welcher Loa...', '', 69497),
(317991, 'deDE', 'Bitte! Wenn Ihr diesen Gefallen nicht nutzt, bleib\' ich hier für immer gefang\'n! Ich geb\' Euch alles, was Ihr wollt, nur bitte, löst den Gefallen ein!', '', 69497),
(317886, 'deDE', 'So gütig von Euch, diesen armen alten Fuchs zu rett\'n! Ihr habt mir \'nen Gefallen getan, also werd\' ich ihn Euch dreifach zurückzahl\'n! Drei Gefallen seien Euer.\n\nWas wünscht Ihr Euch für den ersten Gefallen?', '', 69497),
(317371, 'deDE', 'Meine... Meine Eltern...', '', 69497),
(317362, 'deDE', 'Konzentriert Euch.', '', 69497),
(316476, 'deDE', 'Sie hab\'n unsren Großvater verlass\'n, unsren Onkel, und dich bald auch.', '', 69497),
(316469, 'deDE', '', 'Warum tust du das?', 69497),
(316440, 'deDE', 'Wisst Ihr, was ich sehe, wenn ich in die Leere blicke?', '', 69497),
(315773, 'deDE', 'TOR! Was für\'n Ende für \'nen actiongeladenen Kopfballtag! Einer, der in die Geschichte eingeh\'n wird, Leute, un\' einer, den ich nich\' so schnell vergess\'n werde.', '', 69497),
(315751, 'deDE', 'Was für \'ne Beinarbeit! Was für \'ne Kopfarbeit!', '', 69497),
(315736, 'deDE', 'Meine Damen un\' Herren, es is\' wieder an der Zeit für das Spiel der Könige un\' den König der Spiele: Kopfball!', '', 69497),
(315715, 'deDE', 'Der Legende nach hat es unser\'n Hexenmeister ZWEI Seelensplitter gekostet, den nächst\'n Herausforderer zu beschwör\'n! Er is\' groß, er is\' blau, un\' ihm gefällt dieser Ort nich\'! Hier kommt Guth\'kar!', '', 69497),
(315706, 'deDE', 'Selbst \'n bunt gemischtes Team aus... wartet, sin\' das etwa $uein:eine:r; $PR un\' \'ne Elfe ohne Hosen? Selbst die!', '', 69497),
(314378, 'deDE', 'Lasst das Experimentieren... beginnen!', '', 69497),
(313757, 'deDE', 'Es tut gut, hier mal ein paar neue Gesichter zu sehen. Meine Mannschaft und ich sind seit über sieben Jahren hier gestrandet, und wir dachten langsam schon, dass wir uns hier ein komplett neues Leben aufbauen müssten!', '', 69497),
(313655, 'deDE', 'Gift brennt tief. Fleisch und Knochen!', '', 69497),
(313623, 'deDE', '', 'Orweyna? Jetzt sprecht ihr mit Nek\'zali. Kniet un\' ich lass Euch leben.', 69497),
(313438, 'deDE', '', 'Jetzt ist mir wieder langweilig.', 69497),
(313337, 'deDE', 'Weg von mir!', '', 69497),
(313292, 'deDE', 'Tortollaner... stink\'n nach Fisch un\' Meer. Widerlich!', '', 69497),
(313265, 'deDE', 'Gerettet? Un\' dann auch noch mit der Hilfe eines Außenseiters. Ich steh\' in Eurer Schuld, $n.', '', 69497),
(313191, 'deDE', 'Hallo! Ihr seht mir wie $uein aufrechter:eine aufrechte:c; $C aus.\n\nViele unserer verwundbarsten Ältesten konnten den Knardinangreifern nicht entkommen, als sie unser Lager überrannten.\n\nDie Jahrhunderte haben sie mit dicken Panzern und weitreichenden Erinnerungen gesegnet, waren allerdings nicht so gütig, was Geschwindigkeit angeht.\n\nWürdet Ihr einigen Altpanzern dabei helfen, in die Freiheit zu entkommen?\n\nUnd wenn Ihr dabei einige der Relikte und Schriftrollen findet, die wir zurücklassen mussten, würden sie uns sehr dabei helfen, uns in unserem neuen Lager einzuleben.', 'Hallo! Ihr seht mir wie $uein aufrechter:eine aufrechte:c; $C aus.\n\nViele unserer verwundbarsten Ältesten konnten den Knardinangreifern nicht entkommen, als sie unser Lager überrannten.\n\nDie Jahrhunderte haben sie mit dicken Panzern und weitreichenden Erinnerungen gesegnet, waren allerdings nicht so gütig, was Geschwindigkeit angeht.\n\nWürdet Ihr einigen Altpanzern dabei helfen, in die Freiheit zu entkommen?\n\nUnd wenn Ihr dabei einige der Relikte und Schriftrollen findet, die wir zurücklassen mussten, würden sie uns sehr dabei helfen, uns in unserem neuen Lager einzuleben.', 69497),
(313079, 'deDE', 'Nein! Das is\' noch nich\' vorbei...', '', 69497),
(312978, 'deDE', 'Ah! Nach Tausenden von Jahren bin ich frei! Zeit für einen neuen, passenden Körper.', '', 69497),
(312896, 'deDE', '', 'Hm... Ihr seht besorgt aus. Kopfschmerzen? Flüche? Oder einfach schlechte Entscheidungen? Ich behandle alle drei… manchmal auf die gleiche Weise.', 69497),
(312775, 'deDE', '', 'Ha. Passt auf, Hash\'ura. Ihr klingt schon wie \'ne Amani.', 69497),
(312568, 'deDE', 'Rot. Dickflüssig. <schlürf> Köstlich.', '', 69497),
(312407, 'deDE', '', 'Hehe. Ihr seid also wieder da?', 69497),
(312364, 'deDE', '', 'Schaut! Die Tür is\' endlich offen! Ich komme, Zul\'jan. Halt durch...', 69497),
(312317, 'deDE', 'Auf dieser Insel gibt\'s Gruseligeres als Schlangen!', '', 69497),
(312311, 'deDE', 'Dieses Ding da... leuchtet vor Macht...', '', 69497),
(311954, 'deDE', '', 'Habt Ihr... Jan gefund\'n?', 69497),
(311951, 'deDE', 'Wie faszinierend... eine beachtliche Quelle der Pein.', '', 69497),
(311938, 'deDE', 'Ihr wirkt recht blass. Ein wenig Gift gefällig?', '', 69497),
(311936, 'deDE', 'Die Schlange ist jetzt zahnlos. Ihr behaltet die Oberhand.', '', 69497),
(311893, 'deDE', '', 'Das ist eine Wahl, auf die man anstoßen kann.', 69497),
(311857, 'deDE', 'Noch \'ne Runde? Ganz nach meinem Geschmack. Ich mag Euch, alter Panda.', '', 69497),
(311849, 'deDE', 'Die Sorgen finden mich trotzdem, aber eben auch ein gutes Bier... meistens gleichzeitig.', '', 69497),
(311846, 'deDE', 'Ihr werdet Eurem Erbe gerecht. Dieses Getränk genießt man in kleinen Schlucken.', '', 69497),
(311845, 'deDE', 'Also... was denkt Ihr?', '', 69497),
(311800, 'deDE', '', 'Die Hash\'ey grüßt Euch.', 69497),
(311779, 'deDE', '', 'Zerenago, geehrter Med\'jai. Andere sin\' gekommen, um uns von unserer Wache zu abzulös\'n.', 69497),
(311769, 'deDE', 'Ah, noch ein forschender Geist!', '', 69497),
(311762, 'deDE', '', 'Er liegt gleich dort drüben. Könnt Ihr ihn ihm zurückbringen?', 69497),
(311691, 'deDE', 'Wir respektier\'n die Toten, aber Ektoplasma is\' nützlich. Sammelt es von den Aggressiven.', '', 69497),
(311583, 'deDE', '', 'Die Kinder von Ula\'tek dürf\'n sich hier nich\' rumtreib\'n. Tötet sie!', 69497),
(311317, 'deDE', '', 'Alles gut. Nur \'n Kratzer. Wir sollt\'n uns im Dorf sammeln.', 69497),
(311250, 'deDE', 'Ugh, is\' nich\' gerade lecker… aber unsere Truppen freu\'n sich über frisches Obst.', '', 69497),
(311241, 'deDE', 'Die Geister ruh\'n. Ich sorge dafür, dass ihre Waffen nich\' ungenutzt bleib\'n.', '', 69497),
(310320, 'deDE', '', 'Ich weiß, dass Ihr meine Sorgen lindern wollt, $n. Doch ich habe erst vor Kurzem begriffen, dass meine Worte Gewicht haben. Ich konnte es nicht erwarten, zwischen unserem zerstrittenen Volk Brücken zu schlagen. Und nun zahlen die Amani den Preis dafür.\n\nIch will das wiedergutmachen. Gemeinsam.', 69497),
(309826, 'deDE', '', 'Nein, ich kann mich nich\' erinnern. Seht Euch in der Nähe des Schiffs um. Vielleicht wandern \'n paar ihrer Seelen noch auf dem Deck rum.', 69497),
(309825, 'deDE', '', 'Jelvik? Oh, ja. Er war \'n fröhlicher Typ. Hat geholf\'n, wo er konnte. Er hatte \'nen Freund... hmmm...', 69497),
(309540, 'deDE', 'Wir müssen $n helfen! Tekkan! Steh nich\' einfach rum!', '', 69497),
(309165, 'deDE', 'Ha. Ihr vertraut immer noch den Loa? Zul\'jan hat jetz\' was Stärkeres.', '', 69497),
(309043, 'deDE', '', 'Unsere Feinde sind unerbittlich... Beseitigt diese Bedrohung, schnell!', 69497),
(308482, 'deDE', 'Wenn Zul\'jan glaubt, wir lass\'n ihn nach all dem hier an Zul\'jarras Stelle herrsch\'n, hat er sich geschnitt\'n.', '', 69497),
(308324, 'deDE', '', 'Großer Loa des Sieges! Die Hash\'ey der Amani erbittet erneut Eure Hilfe!', 69497),
(308186, 'deDE', 'Malacrass muss mit Zul\'jan im Tempel sein. Sie sin\' jetzt beide Feinde der Amani.', '', 69497),
(308043, 'deDE', 'Die Zwielichtklinge gehörte zu Xal\'ataths Gefolge. Sie müssen jetzt immer noch etwas über ihren Aufenthaltsort wissen.\n\nUnd wenn wir herausfinden, was sie wissen, können wir Xal\'atath aufspüren und sie für ihre Taten zur Rechenschaft ziehen.', '', 69497),
(307747, 'deDE', '', 'Ihr seht nich\' besonders stark aus. Seid Ihr sicher, dass Ihr kämpfen wollt? Seid Ihr \'n würdiger Gegner?', 69497),
(307386, 'deDE', 'Ich weiß nicht, wo Xal\'atath ist. Aber jetzt, wo Ula\'tek tot ist, kann Kith\'ix ungehindert wieder auferstehen!', '', 69497),
(307346, 'deDE', 'Ist das... Antenorian? Unmöglich!', '', 69497),
(307324, 'deDE', 'Für Arator war unser Sieg am Morgenbrunnen von kurzer Dauer. Er will nur seine Eltern finden... und Xal\'atath.', '', 69497),
(304905, 'deDE', 'Nek\'zali! Hier drüb\'n! Wir brauch\'n Heilung!', 'Nek\'zali! Hier drüb\'n! Wir brauch\'n Heilung!', 69497),
(304870, 'deDE', '', 'Eine Macht, älter un\' mächtiger als die Loa! Damit überleb\'n die Amani!', 69497),
(304688, 'deDE', 'Ha! Dieser Körper tanzt an meinen Fäden!', '', 69497),
(304072, 'deDE', 'Ihr werdet nich\' passier\'n. Ihr dürft nich\' seh\'n.', '', 69497),
(303912, 'deDE', '', 'Sie hat uns sicher nicht grundlos hergeführt.', 69497),
(324314, 'deDE', '', 'Warum nicht? Ich bin Händler und kaufe und verkaufe Waren aller Völkern der Allianz. Alles, was derart meisterhaft gefertigt ist, verdient meine Aufmerksamkeit. Und auch Eure.\n\nUnd falls es Euch beruhigt: Der Traktor wurde von einem Gnom aus Westfall gebaut, nicht von einem Menschen.', 69497),
(324310, 'deDE', '', 'Willkommen. Ich führe einige der erlesensten Waren, die ich aus den Ländern der Menschen von Westfall importiert habe.', 69497),
(317690, 'deDE', 'Nexushauptmann Leth\'ir,\n\ntrotz Eurer Aktionen übertreffen die Manaverarbeitungsquoten auf Naigtal alle Erwartungen.\n\nDaher wird das Authorotum Elite-Agenten einsetzen, um den Erfolg von Operation Archenmeerfunke sicherzustellen.\n\nAgentenakte:\n\n- Zauberwerferin Rem\'lazar, Aufseherin der Manaschmiede Oltani\n- Abtrünniger Kulivero, Ehemaliger Phasenkommandant\n- Technomedikus Alazj, Erztechnomant\n- Wächter Halazir, Alazjs neuestes Mechanoidenmodell\n- Raumkrümmungsagent Xi\'grivr, [Geschwärzt]\n- Konstruktaufseherin Ahl\'syraz, Die Nullarchitektin\n- [Geschwärzt]\n\n- Entsendungskonsul des Authorotums', 'Nexushauptmann Leth\'ir,\n\nTrotz Eurer Aktionen übertreffen die Manaverarbeitungsquoten auf Naigtal alle Erwartungen.\n\nDaher wird das Authorotum Elite-Agenten einsetzen, um den Erfolg von Operation Archenmeerfunke sicherzustellen.\n\nAgentenakte:\n\n- Zauberwerferin Rem\'lazar - Aufseherin der Manaschmiede Oltani\n- Abtrünniger Kulivero - Ehemaliger Phasenkommandant\n- Technomedikus Alazj - Erztechnomant\n- Wächter Halazir - Alazjs neuestes Mechanoidenmodell\n- Raumkrümmungsagent Xi\'grivr - [Geschwärzt]\n- Konstruktaufseherin Ahl\'syraz - Die Nullarchitektin\n- [Geschwärzt]\n\n- Entsendungskonsul des Authorotums', 69497),
(317689, 'deDE', 'Nexushauptmann Leth\'ir,\n\nEure jüngsten Handlungen sind ein eklatanter Beweis für Ungehorsam und beispiellose Unvernunft.\n\nEure nicht genehmigten feindlichen Aktivitäten auf Azeroth haben die Hal\'hadar auffliegen lassen.\n\nDas Authorotum hätte jeden Grund, Euch Eures Ranges zu entheben und Eure ungebundene Gestalt in der nächsten Heraazi-Sonne zu entsorgen.\n\nGlücklicherweise ist es mir gelungen, es vorerst davon abzubingen.\n\nNun da Naigtals Manaschmieden funktionstüchtig sind, werdet Ihr angewiesen, Euch aus Azeroth zurückzuziehen und die Feindseligkeiten einzustellen.\n\n- Archenkanzler Ahl\'dynsir', '', 69497),
(317687, 'deDE', 'Nexushauptmann Leth\'ir,\n\nOperation Archenmeerfunke hat für das Authorotum oberste Priorität.\n\nDie Verzögerungen im Sodaraam-Sektor werden mit feindseligen Aktionen der Rebellen in Verbindung gebracht, die im Komm-Protokoll: Beta-J21 erwähnt wurden.\n\nIhr werdet auf die Lieferung und den Einsatz von Arbeitskräften warten, sobald die Verschiffungshäfen freigegeben wurden.\n\n- Entsendungskonsul des Authorotums', 'Nexushauptmann Leth\'ir,\n\nOperation Archenmeerfunke hat für das Authorotum oberste Priorität.\n\nDie Verzögerungen im Sodaraam-Sektor werden mit feindseligen Aktionen der Rebellen in Verbindung gebracht, die im Komm-Protokoll: Beta-J21 erwähnt wurden.\n\nIhr werdet auf die Lieferung und den Einsatz von Arbeitskräften warten, sobald die Verschiffungshäfen freigegeben wurden.\n\n- Entsendungskonsul des Authorotums', 69497),
(317686, 'deDE', 'Entsendungskonsul,\n\ndies ist die vierte Holonachricht, die ich geschickt und auf die ich noch keine Antwort erhalten habe.\n\nDie Lieferung der Manazellen aus Sodaraam ist noch nicht eingetroffen und meine Streitkräfte stehen bereit für ihren Einsatz.\n\nOhne vorläufige Manavorräte können wir kein komplettes Manaschmiedenetz, geschweige denn eine einzige Leitung errichten.\n\nIch erbitte umgehend eine Umleitung von Manazellen aus anderen funktionsfähigen Netzen.\n\nEuer ergebenster und geduldiger Diener\n\nNexushauptmann Leth\'ir', 'Entsendungskonsul,\n\ndies ist die vierte Holonachricht, die ich geschickt und auf die ich noch keine Antwort erhalten habe.\n\nDie Lieferung der Manazellen aus Sodaraam ist noch nicht eingetroffen und meine Streitkräfte stehen bereit für ihren Einsatz.\n\nOhne vorläufige Manavorräte können wir kein komplettes Manaschmiedenetz, geschweige denn eine einzige Leitung errichten.\n\nIch erbitte umgehend eine Umleitung von Manazellen aus anderen funktionsfähigen Netzen.\n\nEuer ergebenster und geduldiger Diener,\n\nNexushauptmann Leth\'ir', 69497),
(317685, 'deDE', 'Nexushauptmann Leth\'ir,\n\nEuer Auftrag lautet, ein Manaschmiedenetz auf der als \"Naigtal\" bezeichneten Welt einzurichten.\n\nDie Ozeane dieser Welt weisen eine hohe Konzentration an Arkanenergie auf, die auch die Biome auf dem Planeten zu beeinflussen scheint.\n\nMit unserer nächsten Lieferung aus dem Sodaraam-Sektor werden erste Manazellen in der Welt eingesetzt.\n\nOperation Archenmeerfunke läuft.\n\n- Entsendungskonsul des Authorotums', '', 69497),
(317350, 'deDE', 'Danke für Eure Hilfe da draußen un\' dafür, dass Ihr La\'una geheilt habt.', '', 69497),
(316943, 'deDE', '', 'Ihr habt Ihn korrumpiert, genau wie uns\'ren Großvater!', 69497),
(316933, 'deDE', 'Wie schwach die Amani geword\'n sin\'...', '', 69497),
(316473, 'deDE', 'Eins, das unsre Gegner fürcht\'n. Und keins, das vor falschen Geistern kriecht.', '', 69497),
(315958, 'deDE', 'Wahnsinn! Der is\' wohl dauerhaft ausge-Gnokt!', '', 69497),
(315957, 'deDE', 'Was is\' das? Er wurde ausge-Gnokt, aber steht er wieder auf? Ihr kriegt ihn niemals dauerhaft klein!', '', 69497),
(315955, 'deDE', 'Es is\' der Spitzenprimat, der erstaunliche Affe, der große Gorilla höchstselbst! Gnok!', '', 69497),
(315953, 'deDE', 'Gnok!', 'Gnok!', 69497),
(315951, 'deDE', 'Wenn ich Gnok sage, sagt Ihr...', '', 69497),
(315214, 'deDE', '', 'Das werde ich.\n\nSeit Ihr Belath diesen Schlüsselstein gebracht habt, habe ich unsere Archive nach Informationen durchkämmt.\n\nAls wir in Antorus eingefallen sind, konnten wir eine Menge Informationen über viele der Welten sichern, die die Legion beansprucht hatte.\n\nNatürlich könnte dieser Wissensschatz nutzlos sein, solange wir nicht wissen, von welcher Welt dieser Schlüsselstein stammt.', 69497),
(315085, 'deDE', '', 'Ich kann Euch nich\' genug dank\'n, $p.\n\nDass Ihr mit dem Heilmittel für La\'una geholf\'n un\' nach dem Rest meines Spähtrupps gesucht habt, bedeutet mir mehr, als ich sag\'n kann.', 69497),
(315002, 'deDE', 'Ich wette, ich bin vor Euch am Forum. Ich gebe Euch sogar einen Vorsprung.', '', 69497),
(313066, 'deDE', 'All die Mühe für nichts.', '', 69497),
(313039, 'deDE', '', 'Die Barriere wird schwächer!', 69497),
(313036, 'deDE', '', 'Zul\'jarra bleibt nicht viel Zeit. Ich gehe vor, Ihr zerstört die Barrieren, Champion!', 69497),
(312774, 'deDE', '', 'Jan wirkte immer, als würd\' ihm ein Geist über die Schulter schau\'n. Als müsse er unsere Ahnen stolz mach\'n.', 69497),
(311940, 'deDE', 'Kaltblütig und gerissen bis zum Ende. Ich respektiere das. Es kann eben nur ein Jäger obsiegen.', '', 69497),
(311615, 'deDE', 'Er beherrscht die Leere zwar nicht, doch seine Entschlossenheit, Xal\'atath zu finden, verleiht ihm die Stärke, ihrer Präsenz zu widerstehen… trotz des Lichts.', '', 69497),
(311605, 'deDE', 'Viele halten mich und alle Leerenelfen für Monster. Ich werde ihnen nicht den Beweis dafür liefern.', '', 69497),
(310494, 'deDE', '', 'Ihr kennt den Rhythmus noch, nicht wahr?', 69497),
(308371, 'deDE', '', 'Wartet. Ich höre... die Stimme der Göttin! Sie ruft uns...', 69497),
(307753, 'deDE', 'Jetz\' entzieh\'n wir den Knochen meine Seele. Werft die Köder!', '', 69497),
(307646, 'deDE', '', 'Ich konnte mich nur daran erinnern, dass ich an jenem Tag Ruhm erring\'n wollte. Aber ich hab vergess\'n, warum ich gekämpft hab.', 69497),
(307379, 'deDE', 'So ist es. Und Antenorian weiß sicher, wie sie das anstellen wollen.', '', 69497),
(307367, 'deDE', 'Aaargh! Nein!', '', 69497),
(305873, 'deDE', '', 'Tefokal is\' nich\' schwer verletzt, aber ich muss mich um seine Wunden kümmern, bevor sie sich entzünden.', 69497),
(304867, 'deDE', 'Rückzug! Bringt die Verletzt\'n in Sicherheit!', '', 69497),
(304624, 'deDE', '', 'Seid still! Un\' diesmal weicht Ihr mir nich\' von der Seite.', 69497),
(308552, 'deDE', 'Sie darf nich\' verehrt werd\'n! Sie muss vergess\'n werd\'n!', '', 69497);
