INSERT INTO `currency_types_locale` (`ID`, `locale`, `Name_lang`, `Description_lang`, `VerifiedBuild`) VALUES
(3356, 'deDE', 'Unbesudelte Manakristalle', 'Kann verdient werden, nachdem Ihr Stufe 9 der Reise des Tiefenforschers erreicht habt. Kann durch das Öffnen von großzügigen Kästen mit restaurierten Kastenschlüsseln in großzügigen Tiefen der Stufe 11 erhalten werden. Kann bei Zah\'ran gegen mächtige Ausrüstung eingetauscht werden.', 69497),
(3418, 'deDE', 'Nebulöser Leerenkern', 'Kann beim Sieg über starke Gegner in Schlachtzügen von Midnight, beim Abschluss von Dungeons auf \'Mythisch+\' oder großzügigen Tiefen und Beutejagden auf dem Schwierigkeitsgrad \'Alptraum\' in mächtige Ausrüstung umgewandelt werden.\n\nGegenstände können einmal pro Schwierigkeitsgrad erhalten werden, bis alle geeigneten Gegenstände für Eure aktuelle Spezialisierung transmutiert wurden.', 69497),
(3509, 'deDE', 'Gezeitenfunkenstaub', 'Magische Rückstände, die zusammen mit Funken der Gezeiten erhalten werden. Werden verwendet, um nachzuverfolgen, wie viele Funken der Gezeiten Ihr in Saison 2 von Midnight bereits erhalten habt.\n\nWenn Ihr während der Saison bei der Menge an Funken hinterherhinkt, könnt Ihr Maximalstufeninhalte wie Tiefen, Mythisch Plus, Schlachtzüge, instanziiertes PvP und einige Ereignisse in der Außenwelt abschließen, um wieder aufzuholen.', 69497);
