INSERT INTO `scenario_step_locale` (`ID`, `locale`, `Description_lang`, `Title_lang`, `VerifiedBuild`) VALUES
(17053, 'deDE', 'Betretet die verfluchten Kammern unterhalb des Siegels des Zorns und schaltet alle Bedrohungen aus.', 'Die Verfluchten Tiefen räumen', 69497),
(17052, 'deDE', 'Findet einen Weg in die Verfluchten Tiefen.', 'Zugang zu den Verfluchten Tiefen', 69497),
(17048, 'deDE', 'Macht Euch bereit, die Schattenseite anzugreifen.', 'Angriffsvorbereitung', 69497),
(17044, 'deDE', 'Betretet die Schattenseite und besiegt die Gegner dort.', 'Die Schattenseite räumen', 69497),
(17032, 'deDE', 'Macht Euch bereit, eine Flut von Schlangen baut sich auf.', 'Aus der Tiefe schlängeln', 69497),
(17030, 'deDE', 'Flammenschürer bereiten die Geisterscheiterhaufen vor.', 'Vorbereitung der Scheiterhaufen', 69497),
(17028, 'deDE', 'Eine seltsame Truhe wurde entdeckt!', 'Truhe untersuchen', 69497),
(16919, 'deDE', 'Betretet mehrere Portale und zerstört Ruuk\'Jars Eier.', 'Das Gelege zerstören', 69497),
(16918, 'deDE', 'Wartet, dass sich das Portal öffnet.', 'Das Portal beschwören', 69497),
(16876, 'deDE', 'Truhe freigeschaltet.', 'Truhe freigeschaltet', 69497),
(16875, 'deDE', 'Bringt die drei Stäbe von jedem Stein zur Truhe.', 'Die Knüppel bergen', 69497),
(16873, 'deDE', 'Sammelt boshafte Geister und verbrennt sie auf Geisterscheiterhaufen. Nehmt die Flammen von den Scheiterhaufen, um entweihte Sarkophage zu vernichten.', 'Läuterung der Untoten', 69497),
(16858, 'deDE', 'Nutzt die Schreine, um Unreinheitskugeln zu sammeln.', 'Die Schreine von Erde und Himmel nutzen', 69497),
(16856, 'deDE', 'Tötet Schlangen und stört Rituale, bevor sie den Tempel überrennen.', 'Die Flut der Schlangen eindämmen', 69497),
(16853, 'deDE', 'Schreine werden für die Verwendung ermächtigt.', 'Die Schreine ermächtigen', 69497),
(17336, 'deDE', 'Kämpft Euch in das Herz des Giftigen Abgrunds und verhindert, dass Ula\'tek aus ihrem Gefängnis entkommt.', 'Das Grab von Ula\'tek', 69497),
(17329, 'deDE', 'Kämpft Euch in das Herz des Giftigen Abgrunds vor und stellt Euch Ula\'tek.', 'Das Grab von Ula\'tek', 69497),
(17328, 'deDE', 'Schlangenmonstrositäten hausen jetzt in den uralten Hallen, in denen die Opfer der Seelenwinder begraben wurden.', 'Der Schlangenbau', 69497),
(17327, 'deDE', 'In der Kammer der Virulenz destilliert Vashnik der Bösartige Ula\'teks Gifte zu immer tödlicheren Varianten.', 'Die Essenz des Gifts', 69497);
